            'github'
        );

        var env = null;
        try { env = java.lang.System.getenv('DEFAULT_TRACKER'); } catch (e) {}
        if (env) {
            // DEFAULT_TRACKER outranks the built-in fallback — the plain default
            // is covered by the dedicated env-probing test below.
